const workspace=document.body.dataset.workspace;const definition=workspaceDefinitions[workspace];const shared={zh:{panelTitle:'告诉 AI 你想完成什么',panelCopy:'你的任务会保留在这一条对话中。',taskLabel:'你的任务',save:'保存到项目',resultsTitle:'AI SuperMall',resultsCopy:'继续补充或修改，让任务一步步完成。',note:'所选文件只保留在当前浏览器会话中，直到安全的专用工具接入。',choose:'选择文件',addMoreImages:'添加更多图片'},en:{panelTitle:'Tell AI what you want to accomplish',panelCopy:'Your task stays in this one conversation.',taskLabel:'Your task',save:'Save to Project',resultsTitle:'AI SuperMall',resultsCopy:'Keep refining the work in this conversation.',note:'Selected files remain only in this browser session until a secure specialist tool is connected.',choose:'Choose file',addMoreImages:'Add more images'}};let language=localStorage.getItem('ai-supermall-language')||'zh',selectedFile=null,selectedImages=[],objectUrl='',assetSequence=0,conversation=[],activeConversationId='',activeProjectId='',queue=Promise.resolve();const $=selector=>document.querySelector(selector);const text=()=>definition[language];const request=async(path,options={})=>{const response=await fetch(path,options);const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Request failed');return body};
function setStatus(message){$('#workspaceStatus').textContent=message||''}function ensureImageModal(){let modal=get('generatedImageModal');if(modal)return modal;modal=document.createElement('div');modal.id='generatedImageModal';modal.className='generated-image-modal';modal.hidden=true;modal.innerHTML='<div class="generated-image-modal-backdrop" data-close-image-modal></div><section class="generated-image-modal-panel" role="dialog" aria-modal="true" aria-label="Generated image preview"><button type="button" class="generated-image-modal-close" data-close-image-modal aria-label="Close image preview">×</button><img id="generatedImageModalImage" alt="Generated image preview"></section>';document.body.append(modal);modal.addEventListener('click',event=>{if(event.target.closest('[data-close-image-modal]'))closeImageModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)closeImageModal()});return modal}function closeImageModal(){const modal=get('generatedImageModal');if(!modal)return;modal.hidden=true;get('generatedImageModalImage').removeAttribute('src')}function openImageModal(url,alt){const modal=ensureImageModal(),image=get('generatedImageModalImage');image.src=url;image.alt=alt||'Generated image';modal.hidden=false}function renderHistory(){const list=$('#workspaceHistory');list.innerHTML='';conversation.forEach(item=>{const card=document.createElement('article'),question=document.createElement('strong'),answer=document.createElement('p');question.textContent=item.question;answer.textContent=item.answer;card.append(question,answer);(Array.isArray(item.images)?item.images:[]).forEach(url=>{const image=document.createElement('img');image.className='generated-image';image.src=url;image.alt='Generated image';image.tabIndex=0;image.setAttribute('role','button');image.setAttribute('aria-label',language==='zh'?'点击查看大图':'Tap to view full image');image.addEventListener('click',()=>openImageModal(url,image.alt));image.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openImageModal(url,image.alt)}});image.addEventListener('error',()=>setStatus(language==='zh'?'生成图片无法加载，链接可能已过期。':'The generated image could not load. Its link may have expired.'),{once:true});card.append(image)});list.append(card)});$('#workspaceResults').hidden=!conversation.length}function applyLanguage(next){language=next;localStorage.setItem('ai-supermall-language',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';const t=text(),s=shared[next],taskPanel=$('#workspaceForm').closest('.workspace-panel');document.title=`AI SuperMall — ${t.title}`;$('#workspaceTitle').textContent=t.title;$('#workspaceDescription').textContent=t.description;$('#uploadLabel').textContent=t.upload;$('#dropText').textContent=t.drop;$('#formatText').textContent=t.formats;$('#uploadButton').textContent=s.choose;$('#taskInput').placeholder=t.prompt;$('#workspaceSubmit').textContent=t.submit;$('#saveProject').textContent=s.save;taskPanel.querySelector('h2').textContent=s.panelTitle;taskPanel.querySelector('p').textContent=s.panelCopy;taskPanel.querySelector('label').textContent=s.taskLabel;$('#workspaceResults').querySelector('h2').textContent=s.resultsTitle;$('#workspaceResults').querySelector('p').textContent=s.resultsCopy;$('.workspace-note').textContent=s.note;$('#homeLink').textContent=next==='zh'?'首页':'Home';$('#projectsLink').textContent=next==='zh'?'我的项目':'My Projects';$('#languageToggle').textContent=next==='zh'?'EN':'中文';if(workspace==='visual')renderImageAssets();else if(selectedFile)setStatus(`${t.local}${selectedFile.name}. ${t.fileOnly}`)}
function clearPreview(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';const preview=get('filePreview');preview.removeAttribute('src');preview.classList.remove('show')}function get(id){return document.getElementById(id)}function isAccepted(file){return definition.accept.split(',').some(rule=>rule==='video/*'?file.type.startsWith('video/'):rule.startsWith('.')?file.name.toLowerCase().endsWith(rule):file.type===rule)}function fingerprint(file){return [file.name,file.size,file.lastModified].join(':')}function assetId(){assetSequence+=1;return typeof crypto?.randomUUID==='function'?crypto.randomUUID():'asset-'+Date.now()+'-'+assetSequence}function releaseAsset(asset){if(asset?.previewUrl)URL.revokeObjectURL(asset.previewUrl);asset.previewUrl='';asset.fallbackUrl=''}function ensureImageAssets(){if(workspace!=='visual')return null;let assets=get('imageAssets');if(assets)return assets;assets=document.createElement('section');assets.className='image-assets';assets.id='imageAssets';assets.hidden=true;const heading=document.createElement('div'),title=document.createElement('strong'),clear=document.createElement('button'),grid=document.createElement('div');heading.className='image-assets-heading';title.id='imageAssetsTitle';clear.id='clearImages';clear.type='button';grid.className='image-assets-grid';grid.id='imageAssetsGrid';heading.append(title,clear);assets.append(heading,grid);get('workspaceStatus').insertAdjacentElement('afterend',assets);clear.addEventListener('click',clearImages);return assets}function showPreview(image,asset){image.src=asset.previewUrl;image.addEventListener('error',()=>{if(asset.fallbackUrl)return;const reader=new FileReader();reader.addEventListener('load',()=>{asset.fallbackUrl=String(reader.result||'');image.src=asset.fallbackUrl},{once:true});reader.readAsDataURL(asset.file)},{once:true})}function renderImageAssets(){const assets=ensureImageAssets();if(!assets)return;const zh=language==='zh',grid=get('imageAssetsGrid'),clear=get('clearImages'),count=selectedImages.length;get('imageAssetsTitle').textContent=zh?'已选图片（'+count+'/10）':'Selected images ('+count+'/10)';clear.textContent=zh?'全部清除':'Clear all';clear.hidden=!count;get('uploadButton').textContent=count?shared[language].addMoreImages:shared[language].choose;grid.replaceChildren();selectedImages.forEach(asset=>{const card=document.createElement('article'),image=document.createElement('img'),name=document.createElement('span'),size=document.createElement('small'),remove=document.createElement('button');image.alt=asset.file.name;showPreview(image,asset);name.textContent=asset.file.name;size.textContent=(asset.file.size/1024/1024).toFixed(1)+' MB';remove.type='button';remove.className='image-asset-remove';remove.textContent='×';remove.title=zh?'删除':'Remove';remove.setAttribute('aria-label',(zh?'删除 ':'Remove ')+asset.file.name);remove.addEventListener('click',()=>removeImage(asset.id));card.append(image,name,size,remove);grid.append(card)});assets.hidden=!count;assets.style.display=count?'':'none'}function removeImage(id){const index=selectedImages.findIndex(asset=>asset.id===id);if(index<0)return;releaseAsset(selectedImages[index]);selectedImages.splice(index,1);renderImageAssets()}function clearImages(){selectedImages.forEach(releaseAsset);selectedImages=[];renderImageAssets();setStatus('')}function appendImages(files){const zh=language==='zh',newFiles=Array.from(files||[]),known=new Set(selectedImages.map(asset=>asset.fingerprint));let added=0,duplicate=0,invalid=0,overLimit=0;newFiles.forEach(file=>{if(!file)return;if(!isAccepted(file)||file.size>definition.maxBytes){invalid+=1;return}const key=fingerprint(file);if(known.has(key)){duplicate+=1;return}if(selectedImages.length>=10){overLimit+=1;return}known.add(key);selectedImages.push({id:assetId(),fingerprint:key,file,previewUrl:URL.createObjectURL(file),fallbackUrl:''});added+=1});renderImageAssets();const messages=[];if(added)messages.push(zh?'已添加 '+added+' 张图片。':added+' image'+(added===1?'':'s')+' added.');if(overLimit)messages.push(zh?'每个任务最多 10 张图片。':'A task can include up to 10 images.');if(invalid)messages.push(zh?'部分文件类型不支持或超过 20 MB。':'Some files are unsupported or exceed 20 MB.');if(duplicate)messages.push(zh?'已跳过重复图片。':'Duplicate images were skipped.');setStatus(messages.join(' '));get('fileInput').value=''}function setFile(file){const t=text();if(!file)return;if(!isAccepted(file)){setStatus(language==='zh'?'此文件类型不受支持。':'This file type is not supported.');return}if(file.size>definition.maxBytes){setStatus(language==='zh'?`文件超过 ${Math.round(definition.maxBytes/1024/1024)} MB 限制。`:`File exceeds the ${Math.round(definition.maxBytes/1024/1024)} MB limit.`);return}selectedFile=file;clearPreview();const preview=$('#filePreview');if(definition.preview!=='none'){objectUrl=URL.createObjectURL(file);preview.src=objectUrl;preview.classList.add('show')}setStatus(`${t.local}${file.name}. ${t.fileOnly}`)}
get('fileInput').accept=definition.accept;get('fileInput').addEventListener('change',event=>{const files=Array.from(event.currentTarget.files||[]);if(workspace==='visual')appendImages(files);else setFile(files[0])});const drop=get('dropZone');['dragenter','dragover'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',event=>{const files=Array.from(event.dataTransfer?.files||[]);if(workspace==='visual')appendImages(files);else setFile(files[0])});window.addEventListener('pagehide',()=>{selectedImages.forEach(releaseAsset);clearPreview()});async function saveConversation(){if(!conversation.length||activeProjectId)return;const signedIn=(await fetch('/api/account/me')).ok;if(!signedIn)return;const existing=Boolean(activeConversationId);const body=existing?{id:activeConversationId,locale:language,messages:conversation}:{title:conversation[0].question.slice(0,120),locale:language,messages:conversation};const result=await request('/api/member/conversations',{method:existing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!existing){const saved=Array.isArray(result)?result[0]:result;activeConversationId=saved?.id||''}}
function scheduleConversationSave(){queue=queue.then(saveConversation).catch(()=>{});return queue}async function updateProject(){if(!activeProjectId)return;await request('/api/member/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:activeProjectId,locale:language,conversation})})}
async function visualFiles(){return Promise.all(selectedImages.map(asset=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({type:asset.file.type,data:String(reader.result||'')});reader.onerror=reject;reader.readAsDataURL(asset.file)})))}document.getElementById('workspaceForm').addEventListener('submit',async event=>{event.preventDefault();const input=document.getElementById('taskInput'),question=input.value.trim();if(!question){input.focus();return}const submit=document.getElementById('workspaceSubmit');submit.disabled=true;setStatus(workspace==='visual'?(language==='zh'?'正在生成图片…':'Generating image…'):'');try{if(workspace==='visual'){const response=await request('/api/visual/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:question,language,images:await visualFiles()})});const images=Array.isArray(response.images)?response.images.filter(url=>typeof url==='string'&&url.trim()):[];if(!images.length)throw new Error(language==='zh'?'图像模型没有返回图片。':'The image model returned no image.');conversation.push({question,answer:response.answer||'',images})}else{const response=await request('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:question,language,context:conversation.slice(-4),taskType:definition.taskType})});conversation.push({question,answer:response.answer||''})}input.value='';renderHistory();setStatus(workspace==='visual'?(language==='zh'?'图片已生成。':'Image generated.'):'');if(activeProjectId)await updateProject();else scheduleConversationSave()}catch(error){setStatus(error.message||'Unable to complete this task.')}finally{submit.disabled=false;input.focus()}});$('#saveProject').addEventListener('click',async()=>{if(!conversation.length)return;try{const me=await fetch('/api/account/me');if(!me.ok){location.href='account.html?mode=login';return}if(activeProjectId){await updateProject()}else{const result=await request('/api/member/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:conversation[0].question.slice(0,120),locale:language,conversation})});const saved=Array.isArray(result)?result[0]:result;activeProjectId=saved?.id||'';activeConversationId=''}setStatus(text().saved)}catch(error){setStatus(error.message||'Unable to save project.')}});
